// Virtual time belongs only to offline test fixtures. Never use it for live data.
const now = 1800000000000;
const base = () => ({simulationClockMs:now, test_only:true, mode:'SIMULATION', market:{pair:'TNK/USDC',active:true,paused:false,status:'active',timestamp:now,bid:0.99,ask:1,availableBase:100}, candidate:{pair:'TNK/USDC',side:'buy',price:1,amount:5,reason:'Fixture sintetic, nu recomandare financiara',ready_to_trade:true}, decision:true, decisionAgeMs:0});
const cases=[];
function add(name, expected, edit=()=>{}) {const x=base();edit(x);cases.push({json:{...x,case:name,expected}});}
add('valid_approved','SIMULATED_APPROVED_NO_ORDER');
add('valid_rejected','REJECTED_NO_ORDER',x=>x.decision=false);
add('wait','INVALID_NO_ORDER',x=>{x.candidate.side='wait';x.candidate.price=null;x.candidate.amount=0;x.candidate.ready_to_trade=false;});
add('over_budget','INVALID_NO_ORDER',x=>x.candidate.amount=11);
add('missing_ask','INVALID_NO_ORDER',x=>delete x.market.ask);
add('stale_market','INVALID_NO_ORDER',x=>x.market.timestamp-=120000);
add('paused','INVALID_NO_ORDER',x=>x.market.paused=true);
add('insufficient_liquidity','INVALID_NO_ORDER',x=>x.market.availableBase=1);
add('numeric_string','INVALID_NO_ORDER',x=>x.candidate.price='1');
add('wrong_price','INVALID_NO_ORDER',x=>x.candidate.price=0.5);
add('wrong_pair','INVALID_NO_ORDER',x=>x.candidate.pair='UNKNOWN/USDC');
add('crossed_book','INVALID_NO_ORDER',x=>x.market.bid=2);
add('approval_string','REJECTED_NO_ORDER',x=>x.decision='true');
add('expired_approval','EXPIRED_NO_ORDER',x=>x.decisionAgeMs=61000);
add('changed_after_approval','BINDING_MISMATCH_NO_ORDER',x=>x.tamper=true);
add('sell_approved','SIMULATED_APPROVED_NO_ORDER',x=>{x.candidate.side='sell';x.candidate.price=0.99;});
add('invalid_mode','INVALID_NO_ORDER',x=>x.test_only=false);
add('future_market','INVALID_NO_ORDER',x=>x.market.timestamp+=60000);
return cases;

return $input.all().map((item,index) => {
const x=item.json, m=x.market||{}, c=x.candidate||{}, errors=[];
const positive=v=>typeof v==='number' && Number.isFinite(v) && v>0;
if(x.test_only!==true || x.mode!=='SIMULATION') errors.push('simulation_required');
if(!['TNK/USDC','RESET/USDC'].includes(c.pair) || m.pair!==c.pair) errors.push('pair');
if(m.active!==true || m.paused!==false || m.status!=='active') errors.push('market_inactive');
const now=x.simulationClockMs;
if(typeof now!=='number'||!Number.isSafeInteger(now)||now<=0)errors.push('invalid_simulation_clock');
if(typeof m.timestamp!=='number' || !Number.isFinite(m.timestamp) || now-m.timestamp>30000 || m.timestamp>now+1000) errors.push('market_timestamp');
if(!positive(m.bid)||!positive(m.ask)||m.bid>m.ask) errors.push('quotes');
if(c.ready_to_trade!==true || !['buy','sell'].includes(c.side)) errors.push('not_ready');
if(!positive(c.price)||!positive(c.amount)) errors.push('numeric_fields');
const notional=c.price*c.amount;
if(!Number.isFinite(notional)||notional<=0||notional>10) errors.push('notional');
if(!positive(m.availableBase)||!positive(c.amount)||c.amount>m.availableBase) errors.push('liquidity');
const quote=c.side==='buy'?m.ask:m.bid;
if(!positive(c.price)||!positive(quote)||Math.abs(c.price-quote)>1e-9) errors.push('price_quote_mismatch');
if(typeof c.reason!=='string'||!c.reason.trim()||c.reason.length>1000) errors.push('reason');
const valid=errors.length===0;
const proposal=valid?{pair:c.pair,side:c.side,price:c.price,amount:c.amount,notionalUSDC:notional,reason:c.reason}:null;
// Unique within this execution; the offline fixture's case is unique. Not a production idempotency store.
const proposal_id=String($execution.id)+':'+x.case;
const snapshot=valid?JSON.stringify(proposal):null;
return {pairedItem:{item:index},json:{...x,valid,errors,proposal,proposal_id,snapshot,createdAt:now,expiresAt:Math.min(now+60000,Number(m.timestamp)+30000),status:valid?'AWAITING_SIMULATED_APPROVAL':'INVALID_NO_ORDER'}};
});

return $input.all().map(item=>{
const x=item.json;
// Local fixture, no Gmail request and no actual user approval.
const approval={approved:x.decision,proposal_id:x.proposal_id,snapshot:x.snapshot};
const proposal=x.tamper?{...x.proposal,amount:x.proposal.amount+1}:x.proposal;
return {json:{...x,proposal,approval,simulatedNow:x.simulationClockMs+x.decisionAgeMs}};
});

return $input.all().map(item=>{
const x=item.json;
let status='REJECTED_NO_ORDER';
if(x.test_only!==true||x.mode!=='SIMULATION'||x.valid!==true) status='INVALID_NO_ORDER';
else if(x.approval?.proposal_id!==x.proposal_id || x.approval?.snapshot!==x.snapshot || JSON.stringify(x.proposal)!==x.snapshot) status='BINDING_MISMATCH_NO_ORDER';
else if(!Number.isFinite(x.simulatedNow)||x.simulatedNow>=x.expiresAt) status='EXPIRED_NO_ORDER';
else if(x.approval?.approved===true) status='SIMULATED_APPROVED_NO_ORDER';
return {json:{...x,approved:status==='SIMULATED_APPROVED_NO_ORDER',status}};
});

const items=$input.all();
if(items.length!==18)throw new Error('Expected exactly 18 offline fixtures; run the complete simulation from Start manual');
const names=new Set(items.map(i=>i.json.case));if(names.size!==18)throw new Error('Duplicate fixture cases');
let valid=0,invalid=0;const errorsByCase={};
for(const item of items){const x=item.json;if(typeof x.valid!=='boolean')throw new Error('valid must be a boolean');if(x.valid)valid++;else invalid++;errorsByCase[x.case]=x.errors;}
const expectedInvalid=new Set(['wait','over_budget','missing_ask','stale_market','paused','insufficient_liquidity','numeric_string','wrong_price','wrong_pair','crossed_book','invalid_mode','future_market']);
for(const i of items)if(i.json.valid===expectedInvalid.has(i.json.case))throw new Error('Unexpected validation result: '+i.json.case+' '+JSON.stringify(i.json.errors));
if(valid!==6||invalid!==12)throw new Error('Incorrect validation split');
return [{json:{mode:'OFFLINE_SIMULATION_ONLY',live_enabled:false,order_sent:false,external_calls:0,validation_passed:true,total:18,valid:6,invalid:12,expectedTerminalCounts:{SIMULATED_APPROVED_NO_ORDER:2,REJECTED_NO_ORDER:2,EXPIRED_NO_ORDER:1,BINDING_MISMATCH_NO_ORDER:1,INVALID_NO_ORDER:12},errorsByCase,cases:items.map(i=>i.json),notice:'Virtual clock only for synthetic fixtures. This does not validate Google, Gmail, n8n runtime, real quotes, fills or PnL.'}}];
